#include "font_cjk.h"

#include <stddef.h>
#include <string.h>

/* The binary is generated by tools/gen_cjk_bitmaps.py and linked into the
 * application with EMBED_FILES (see components/onepage_c61/CMakeLists.txt). */
extern const uint8_t font_gb2312_24_bin_start[] asm("_binary_font_gb2312_24_bin_start");
extern const uint8_t font_gb2312_24_bin_end[] asm("_binary_font_gb2312_24_bin_end");

#define FONT_MAGIC "OPF1"
#define FONT_VERSION 1
#define FONT_HEADER_BYTES 16

typedef struct __attribute__((packed)) {
  char magic[4];
  uint16_t version;
  uint8_t px;
  uint8_t row_bytes;
  uint32_t count;
  uint32_t reserved;
} font_header_t;

typedef struct __attribute__((packed)) {
  uint32_t codepoint;
  uint8_t bitmap[FONT_CJK_GLYPH_BYTES];
} font_glyph_t;

_Static_assert(sizeof(font_header_t) == FONT_HEADER_BYTES, "font header layout");
_Static_assert(sizeof(font_glyph_t) == 4 + FONT_CJK_GLYPH_BYTES, "font glyph layout");

static const font_header_t *header(void) { return (const font_header_t *)font_gb2312_24_bin_start; }

static const font_glyph_t *glyphs(void) {
  return (const font_glyph_t *)(font_gb2312_24_bin_start + FONT_HEADER_BYTES);
}

static int table_valid(void) {
  const size_t bytes = (size_t)(font_gb2312_24_bin_end - font_gb2312_24_bin_start);
  const font_header_t *h = header();
  if (bytes < FONT_HEADER_BYTES || memcmp(h->magic, FONT_MAGIC, 4) != 0) {
    return 0;
  }
  if (h->version != FONT_VERSION || h->px != FONT_CJK_PX ||
      h->row_bytes != FONT_CJK_ROW_BYTES) {
    return 0;
  }
  if (h->count == 0 || FONT_HEADER_BYTES + (size_t)h->count * sizeof(font_glyph_t) > bytes) {
    return 0;
  }
  return 1;
}

const uint8_t *font_cjk_lookup(uint32_t codepoint) {
  if (!table_valid()) {
    return NULL;
  }
  const font_glyph_t *table = glyphs();
  size_t low = 0;
  size_t high = header()->count;
  while (low < high) {
    const size_t mid = low + (high - low) / 2;
    if (table[mid].codepoint == codepoint) {
      return table[mid].bitmap;
    }
    if (table[mid].codepoint < codepoint) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  return NULL;
}

int font_cjk_count(void) {
  return table_valid() ? (int)header()->count : 0;
}
